// yeuCau = "request", mucDich = "purpose", nguoiDung = "users", ketQua = "result"
const yeuCau = {
  mucDich: "",
  nguoiDung: "",
  ketQua: [],
};

function kiemTra(y) {
  const loi = [];
  if (y.mucDich.trim().length < 15) loi.push("purpose is too short or empty");
  if (!y.nguoiDung.toLowerCase().includes("phone")) loi.push("you did not say customers view it on a phone");
  const ds = y.ketQua.map((k) => k.toLowerCase());
  if (!ds.some((k) => k.includes("opening hours"))) loi.push("missing: opening hours");
  if (!ds.some((k) => k.includes("call button"))) loi.push("missing: call button");
  if (ds.some((k) => ["nice", "modern", "professional"].some((t) => k.includes(t)))) {
    loi.push("vague adjective found: state something you can check");
  }
  return loi;
}

const loi = kiemTra(yeuCau);
console.log(loi.length === 0 ? "Brief passed: the AI has all three things it needs to hit the mark." : "Not yet:");
for (const l of loi) console.log("- " + l);

